import React from 'react';
import { Box, Typography, Card, CardContent, Button, Divider } from '@mui/material';

const LoanScreen = () => {
  return (
    <Box p={2}>
      <Typography variant="h5" gutterBottom>สินเชื่อของคุณ</Typography>

      <Card sx={{ mb: 2 }}>
        <CardContent>
          <Typography variant="h6">ยอดคงเหลือ: ฿120,000</Typography>
          <Typography>เงินดาวน์: ฿30,000</Typography>
          <Typography>ยอดผ่อนต่อเดือน: ฿5,000</Typography>
        </CardContent>
      </Card>

      <Typography variant="h6" gutterBottom>ประวัติการชำระเงิน</Typography>
      <Card sx={{ mb: 2 }}>
        <CardContent>
          <Typography>ส.ค. 2025 - ชำระแล้ว ฿5,000</Typography>
          <Typography>ก.ค. 2025 - ชำระแล้ว ฿5,000</Typography>
        </CardContent>
      </Card>

      <Divider sx={{ my: 2 }} />

      <Box display="flex" gap={2}>
        <Button variant="contained" color="primary">ขอเพิ่มวงเงิน</Button>
        <Button variant="outlined" color="primary">ดูรายละเอียดสัญญา</Button>
      </Box>
    </Box>
  );
};

export default LoanScreen;
